        ["She likes to be tickled hehehehe."] = "A ella le gusta que le hagan cosquillas jejejeje.",
        ["Okay..."] = "Está bien...",
        ["Choose an option:"] = "Elige una opción:",
        ["What's wrong?"] = "¿Qué pasa?",
        ["I'll leave you to it then..."] = "Entonces te dejo con eso...",
        ["Pst, wanna hear a secret?"] = "Pst, ¿quieres escuchar un secreto?",
        ["Sure!"] = "¡Claro!",
        ["They've got six legs... SIX!"] = "Tienen seis patas... ¡SEIS!",
        ["No thanks."] = "No, gracias.",
        ["About my potato cacti..."] = "Acerca de mis cactus de papa...",
        ["Oh, them. Not got none of them. Got some paper, though. Here, you can have it… before they get it."] = "Oh, ellos. No tengo ninguno de ellos. Pero tengo algo de papel. Aquí puedes tenerlo... antes de que lo consigan.",
        ["No...but about my potato cacti..."] = "No...pero sobre mis cactus de patata...",
        ["What? Not got none of them. They probably eat them. I'll have more in [X] days."] = "¿Qué? No tengo ninguno de ellos. Probablemente se los coman. Tendré más en [X] días.",
        ["What? Not got any of them for you. You might be one of them."] = "¿Qué? No tengo ninguno para ti. Podrías ser uno de ellos.",
    },
    ["Wellington"] = {
        ["You hand [number] fish to Wellington."] = "Le entregas el pescado [número] a Wellington.",
        ["Select an Option"] = "Selecciona una opción",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["There's great fishing to be had here. The tropical trout are frisky, but just the thing for cooking up a tasty summer treat."] = "Aquí se puede pescar muy bien. Las truchas tropicales son juguetonas, pero ideales para preparar un sabroso manjar de verano.",
        ["[Using the fishing spots gives you fishing experience. You can gain extra experience for handing the fish to Wellington or delivering them to the barbecue area.]"] = "[Usar los lugares de pesca te brinda experiencia de pesca. Puedes adquirir experiencia adicional entregando el pescado a Wellington o entregándolo en la zona de barbacoa.]",
        ["Why are there pirate ships?"] = "¿Por qué hay barcos piratas?",
        ["Those ships are feisty ones! They're looking for something to fight."] = "¡Esos barcos son luchadores! Están buscando algo con qué luchar.",
        ["If you have any battleships you can pit them against one of the pirate ships but beware, {{Colour|#FF0000|the pirates never lose}}!"] = "Si tienes acorazados, puedes enfrentarlos contra uno de los barcos piratas, pero ¡cuidado, {{Colour|#FF0000|los piratas nunca pierden}}!",
        ["How are things going?"] = "¿Cómo van las cosas?",
        ["I can't complain. {{Sic|Sunshine and fish what more could a man want?}}"] = "No me puedo quejar. {{Sic|Sunshine and fish what more could a man want?}}",
        ["Although, saying that, I wouldn't mind getting my hands on that beastie in the pool. She'd make a meal fit for a kingdom."] = "Aunque, dicho esto, no me importaría tener en mis manos a esa bestia en la piscina. Haría una comida digna de un reino.",
        ["I might need a bigger rod though!"] = "¡Quizás necesite una caña más grande!",
        ["Here take it, I don't want to be involved in this {{Sic|fishyness}}!"] = "¡Toma, no quiero involucrarme en este {{Sic|fishyness}}!",
        ["[You need 1 free space in our backpack to receive your clue caskets.]"] = "[Necesitas 1 espacio libre en nuestro backpack para recibir tus cofres de pistas.]",
        ["[You are handed a casket!]"] = "[¡Te entregan un ataúd!]",
    },
    ["Wemund"] = {
        ["What can I interest you in? Need any pipes? I make very sturdy pipes."] = "¿En qué te puedo interesar? ¿Necesitas alguna tubería? Hago tubos muy resistentes.",
        ["No, not really... what kind of shop is this anyway?"] = "No, en realidad no... ¿qué tipo de tienda es esta?",
        ["Why, it's Wemund's Wrench Warehouse. Wemund, that's me. I don't really sell just wrenches, you know, I sell anything related to the maintenance of dwarven steam machines. Sometimes I do repair work as well. Or I send my assistant."] = "Bueno, es el almacén de llaves de Wemund. Wemund, ese soy yo. Realmente no vendo solo llaves inglesas, ya sabes, vendo cualquier cosa relacionada con el mantenimiento de las máquinas de vapor enanas. A veces también hago trabajos de reparación. O envío a mi asistente.",
        ["Who's he then?"] = "¿Quién es entonces?",
        ["Oh, he's right over there... used to work in the mines to the south, poor lad. Made a bit of a mess of things I believe. So what'll it be then? Got any ship engines to repair?"] = "Oh, él está justo allí... solía trabajar en las minas del sur, pobre muchacho. Hizo un poco de lío con las cosas que creo. Entonces, ¿qué será entonces? ¿Tienes algún motor de barco que reparar?",
        ["Thanks, but I don't think your services are required."] = "Gracias, pero no creo que tus servicios sean necesarios.",
    },
    ["Wendy"] = {
        ["Oh, hello."] = "Oh, hola.",
        ["Choose an option:"] = "Elige una opción:",
        ["Who are you?"] = "¿Quién eres?",
        ["Me? I'm Wendy. I'm learning the ways of witchcraft from Maggie here. She's very clever, you know...and very patient."] = "¿Yo? Soy Wendy. Estoy aprendiendo los métodos de brujería de Maggie aquí. Ella es muy inteligente, ya sabes... y muy paciente.",
        ["What are you doing?"] = "¿Qué estás haciendo?",
        ["I'm travelling with Maggie, trying to learn the ways of witchcraft."] = "Estoy viajando con Maggie, tratando de aprender los métodos de la brujería.",
        ["And what are you learning at the moment?"] = "¿Y qué estás aprendiendo en este momento?",
        ["I'm learning all about - um, hold on...let me just think..."] = "Estoy aprendiendo todo sobre... um, espera... déjame pensar...",
        ["It was something really quite fascinating, I'm sure..."] = "Fue algo realmente fascinante, estoy seguro...",
        ["Uh..."] = "Eh...",
        ["Hmm..."] = "Mmm...",
        ["Look, don't worry about it, really."] = "Mira, no te preocupes por eso, de verdad.",
        ["Sorry, I can't quite recall at the moment, but I'm sure it will come back to me, sooner or later."] = "Lo siento, no lo recuerdo bien en este momento, pero estoy seguro de que lo recordaré tarde o temprano.",
        ["You look a little lost."] = "Pareces un poco perdido.",
        ["If you don't mind my saying so, you look a little lost."] = "Si no te importa que te lo diga, pareces un poco perdido.",
        ["It's funny - I get that a lot! I don't think I'm lost...not at the moment, at least."] = "Es gracioso. ¡Lo entiendo mucho! No creo que esté perdido... no por el momento, al menos.",
        ["Keeping track of where one is isn't a problem, is it? I think it's more that I keep forgetting where I'm going."] = "Mantener un registro de dónde estás no es un problema, ¿verdad? Creo que es más que sigo olvidando hacia dónde voy.",
        ["Select an Option"] = "Selecciona una opción",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Well, it's just that there are so many interesting things to do and see, really!"] = "Bueno, es que hay tantas cosas interesantes que hacer y ver, ¡de verdad!",
        ["It's all well and good to make plans for myself, but I always seem to get distracted along the way."] = "Está muy bien hacer planes para mí, pero parece que siempre me distraigo en el camino.",
        ["Distracted? By what?"] = "¿Distraído? ¿Por qué?",
        ["Oh, well, you know. A pretty flower. A little impling flying by. A fluffy cat that looks like it needs a scratch under its chin."] = "Oh, bueno, ya sabes. Una bonita flor. Un poco de implicación que pasa volando. Un gato peludo que parece necesitar un rasguño debajo de la barbilla.",
        ["I see things like that and my best-laid plans just seem to fly right out of my head!"] = "¡Veo cosas así y mis mejores planes parecen salirse volando de mi cabeza!",
        ["Hmm, I can see how they might."] = "Hmm, puedo ver cómo podrían hacerlo.",
        ["So where are you going?"] = "Entonces, ¿adónde vas?",
        ["Well, Maggie has been teaching me the basics of witchcraft."] = "Bueno, Maggie me ha estado enseñando los conceptos básicos de la brujería.",
        ["I'm sure she sent me out to collect something but, come to think of it, I can't quite remember what it was."] = "Estoy seguro de que me envió a recoger algo pero, ahora que lo pienso, no recuerdo muy bien qué era.",
        ["Well, perhaps it was something for a potion? Or a spell?"] = "Bueno, ¿tal vez era algo para una poción? ¿O un hechizo?",
        ["Oo, that sounds possible! Do you remember what it might have been?"] = "¡Oh, eso suena posible! ¿Recuerdas lo que pudo haber sido?",
        ["Well, given that I wasn't there for the conversation, I have no way of knowing that, I'm afraid."] = "Bueno, dado que no estuve allí durante la conversación, me temo que no tengo forma de saberlo.",
        ["Oh. Sad."] = "Ah. Triste.",
        ["Wait, what were we talking about again?"] = "Espera, ¿de qué estábamos hablando otra vez?",
        ["Look, don't worry about it, okay?"] = "Mira, no te preocupes, ¿vale?",
        ["Have you seen that purple cat wandering around?"] = "¿Has visto ese gato morado deambulando?",
        ["Let's talk about purple cats."] = "Hablemos de gatos morados.",
        ["Can you make my cat purple?"] = "¿Puedes hacer que mi gato sea morado?",
        ["Of course. Just bring your cat to me and let me hold her for a moment. I'll sort her out in no time."] = "Por supuesto. Solo tráeme a tu gato y déjame abrazarlo por un momento. La solucionaré en poco tiempo.",
        ["Of course. Just pick up your cat and hand her to me so that I can take a closer look."] = "Por supuesto. Simplemente toma a tu gato y dámelo para que pueda verlo más de cerca.",
        ["Of course. Just hand your cat to me so that I can take a closer look."] = "Por supuesto. Solo pásame tu gato para que pueda verlo más de cerca.",
        ["Can you remove the purple from a cat?"] = "¿Puedes quitarle el morado a un gato?",
        ["I'm afraid that once the spell is cast, it's cast for good. I haven't figured out how to undo the purple yet."] = "Me temo que una vez que se lanza el hechizo, se lanza para siempre. Aún no he descubierto cómo deshacer el morado.",
        ["Ah, right. Hmm."] = "Ah, claro. Mmm.",
        ["Could you make this cat purple for me?"] = "¿Podrías hacerme este gato morado?",
        ["I can, but I should warn you: I can make cats purple, but I don't know how to change them back. It's a permanent change! Is that okay?"] = "Puedo, pero debo advertirte: puedo hacer que los gatos sean morados, pero no sé cómo volver a cambiarlos. ¡Es un cambio permanente! ¿Está bien?",
        ["Yes, please make my cat permanently purple."] = "Sí, por favor haz que mi gato sea permanentemente morado.",
        ["There you go! Oh, such a beautiful colour."] = "¡Ahí lo tienes! Oh, que color tan bonito.",
        ["Thank you."] = "Gracias.",
        ["No, I think I'll hold off for the time being."] = "No, creo que lo esperaré por el momento.",
        ["Okay. If you change your mind, let me know."] = "Está bien. Si cambias de opinión, dímelo.",
        ["Oh, what a lovely cat you have there. Hello, kitty!"] = "Oh, qué lindo gato tienes ahí. ¡Hola gatito!",
        ["Can you change this cat back to its normal colour?"] = "¿Puedes cambiar este gato a su color normal?",
        ["Um, did I forget to mention...once the spell is cast, it's cast for good. I can't undo the purple."] = "Um, ¿me olvidé de mencionar... una vez que se lanza el hechizo, se lanza para siempre? No puedo deshacer el morado.",
    },
    ["Werewolf (Werewolf Agility Course)"] = {
        ["What's beneath the trapdoor?"] = "¿Qué hay debajo de la trampilla?",
        ["That's none of your business, human, and I'll never tell."] = "Eso no es de tu incumbencia, humano, y nunca lo diré.",
        ["Oh, come on - I'm only curious."] = "Oh, vamos, solo tengo curiosidad.",
        ["If it wasn't my duty to stand here and guard our agility course from the likes of you, I would be relieving you of your life right now."] = "Si no fuera mi deber quedarme aquí y proteger nuestro curso de agilidad de gente como tú, te estaría quitando la vida ahora mismo.",
        ["So it's an agility course, then?"] = "¿Entonces es un curso de agilidad?",
        ["No ... yes ... oh blast - you didn't hear me say anything, right?"] = "No... sí... oh, carajo, no me escuchaste decir nada, ¿verdad?",
        ["No problem. Can I come in?"] = "No hay problema. ¿Puedo entrar?",
        ["No, human - it's werewolves only."] = "No, humano, son solo hombres lobo.",
        ["I'm not a human, I'm a werewolf."] = "No soy un humano, soy un hombre lobo.",
        ["You can tell by my...errr....stunningly fluffy tail."] = "Se nota por mi... errr... cola increíblemente esponjosa.",
        ["You smell of human...and your tail is attached by a peg."] = "Hueles a humano... y tu cola está sujeta por una clavija.",
        ["Erm...woof?"] = "Erm... ¿guau?",
        ["Har har har."] = "Har, har, har.",
        ["I guess I deserved that."] = "Supongo que me lo merecía.",
        ["It's an agility course designed for lycanthropes like ourselves, my friend."] = "Es un curso de agilidad diseñado para licántropos como nosotros, amigo mío.",
        ["Can I come in and use it?"] = "¿Puedo entrar y usarlo?",
        ["Certainly. The cavern contains two courses: on the west side is a level 60 Agility Course, and on the east side is a level 25 Skullball Course."] = "Por supuesto. La caverna contiene dos recorridos: en el lado oeste hay un recorrido Agility de nivel 60 y en el lado este hay un recorrido Skullball de nivel 25.",
        ["You can't go down there, human. If it wasn't my duty to guard this trapdoor, I would be relieving you of the burden of your life right now."] = "No puedes bajar ahí, humano. Si no fuera mi deber proteger esta trampilla, te estaría liberando de la carga de tu vida ahora mismo.",
        ["Good luck down there, my friend. Remember, to the west is the main agility course, while to the east is a skullball course."] = "Buena suerte ahí abajo, amigo mío. Recuerde, hacia el oeste está el campo principal de agilidad, mientras que hacia el este está el campo Skullball.",
    },
